import React from 'react';
import { Link } from 'react-router-dom';

function Navbar({ userId }) {
  return (
    <nav style={{ padding: '10px', background: '#333', color: 'white' }}>
      <Link to="/" style={{ color: 'white', margin: '0 10px' }}>Home</Link>
      {!userId ? (
        <Link to="/signin" style={{ color: 'white', margin: '0 10px' }}>Sign In</Link>
      ) : (
        <>
          <Link to="/dashboard" style={{ color: 'white', margin: '0 10px' }}>Dashboard</Link>
          <Link to="/recipes" style={{ color: 'white', margin: '0 10px' }}>Recipes</Link>
          <Link to="/ask" style={{ color: 'white', margin: '0 10px' }}>Ask AI</Link>
          <Link to="/payment" style={{ color: 'white', margin: '0 10px' }}>Upgrade</Link>
        </>
      )}
    </nav>
  );
}

export default Navbar;
